1	//! The first search stage: walks a root and returns, per file, the lines that match any query pattern.
2	
3	use std::collections::BTreeMap;
4	use std::io;
5	use std::sync::{Arc, Mutex};
6	
7	use camino::{Utf8Path, Utf8PathBuf};
8	use grep_regex::{RegexMatcher, RegexMatcherBuilder};
9	use grep_searcher::{BinaryDetection, Searcher, SearcherBuilder, Sink, SinkContext, SinkMatch};
10	use ignore::WalkBuilder;
11	use ignore::gitignore::Gitignore;
12	use rayon::prelude::*;
13	use rustc_hash::FxHashMap;
14	
15	use crate::error::{MonoklError, Result};
16	use crate::types::LineHit;
17	
18	/// The default for [`TextSearchOptions::max_files`].
19	pub const DEFAULT_MAX_FILES: usize = 100_000;
20	
21	/// Options for [`search_files`].
22	///
23	/// # Examples
24	///
25	/// ```
26	/// use monokl::text_search::TextSearchOptions;
27	///
28	/// let opts = TextSearchOptions { allow_tests: true, ..TextSearchOptions::default() };
29	/// assert!(opts.respect_ignore_files);
30	/// ```
31	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
32	pub struct TextSearchOptions {
33	    /// Searches test files too. When false, a file is skipped if its path below the root has a `__tests__`, `test`,
34	    /// `tests` or `spec` directory, or ends in `.test.ts`, `.test.tsx`, `.test.js`, `.spec.ts`, `.spec.tsx` or
35	    /// `.spec.js`. Matching is case-sensitive.
36	    pub allow_tests: bool,
37	    /// Skips hidden files and what `.gitignore` and `.ignore` files inside the root exclude, with or without a `.git`
38	    /// directory. When the root lies inside a git repository (the nearest ancestor with a `.git` entry), the
39	    /// `.gitignore` and `.ignore` files of the directories from the repository root down to the root's parent apply
40	    /// too, as they do for ripgrep, and rules inside the root take precedence over them. Nothing above the repository
41	    /// root is read, and without a `.git` ancestor no parent is read. `.git/info/exclude` and the user's global
42	    /// excludes are never read, so the same checkout gives the same result on every machine.
43	    pub respect_ignore_files: bool,
44	    /// The most files whose hits are kept. Matching files past it are still searched and counted.
45	    pub max_files: usize,
46	}
47	
48	impl Default for TextSearchOptions {
49	    /// Skips tests, honors ignore files and keeps up to [`DEFAULT_MAX_FILES`] files.
50	    fn default() -> Self {
51	        Self { allow_tests: false, respect_ignore_files: true, max_files: DEFAULT_MAX_FILES }
52	    }
53	}
54	
55	/// What [`search_files`] found.
56	#[derive(Clone, Debug, Default, PartialEq, Eq)]
57	#[non_exhaustive]
58	pub struct TextSearchResult {
59	    /// The kept files, keyed by `root` joined with the path below it, each with its matching lines in line order.
60	    pub hits: BTreeMap<Utf8PathBuf, Vec<LineHit>>,
61	    /// Every file with at least one matching line, kept or not.
62	    pub files_total: u64,
63	    /// Whether `files_total` exceeded [`TextSearchOptions::max_files`], so some matching files have no hits stored.
64	    pub ceiling_hit: bool,
65	    /// In walk order and each listed once, keyed like `hits`: files that could not be read, directories that could not
66	    /// be listed, and ignore files that could not be read or parsed. A parent ignore file above the root is named by its
67	    /// canonical path.
68	    pub unreadable: Vec<Utf8PathBuf>,
69	    /// How many regular files were skipped because their path is not UTF-8.
70	    pub non_utf8_paths: u64,
71	    /// How many walk errors below the root carried no UTF-8 path to put in `unreadable`.
72	    pub walk_errors_without_path: u64,
73	}
74	
75	/// Searches every regular file under `root` for lines matching any of `patterns`, regexes matched case-insensitively
76	/// with Unicode case folding.
77	///
78	/// A pattern sees each line without its `\n` or `\r\n` terminator, exactly the text a hit reports, so `^` and `$`
79	/// anchor at the line's start and end in LF and CRLF files alike, and a pattern for `\n` matches no line.
80	///
81	/// Each directory's entries are visited in byte order of their file names, so the result is the same on every run.
82	/// Symbolic links are neither followed nor searched. Binary files (any NUL byte) are skipped silently, even when a
83	/// matching line is also not UTF-8. A matching line that is not UTF-8 is a hit with each invalid byte sequence
84	/// replaced by U+FFFD. A file that cannot be read, and any walk failure below `root`, go in
85	/// [`unreadable`](TextSearchResult::unreadable) and the search continues. No patterns
86	/// means nothing to search: once `root` is checked, the result is empty and nothing is walked.
87	///
88	/// # Errors
89	///
90	/// - [`MonoklError::RegexBuild`] if any pattern does not compile, before `root` is checked.
91	/// - [`MonoklError::Walk`] with `path` set to `root` if `root` is missing, is not a directory or cannot be listed,
92	///   even when there are no patterns.
93	///
94	/// # Examples
95	///
96	/// ```
97	/// use camino::Utf8Path;
98	/// use monokl::text_search::{search_files, TextSearchOptions};
99	///
100	/// let dir = tempfile::tempdir()?;
101	/// std::fs::write(dir.path().join("a.ts"), "const Alpha = 1;\nconst beta = 2;\n")?;
102	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
103	///
104	/// let result = search_files(root, &["alpha", "gamma"], &TextSearchOptions::default())?;
105	/// let lines = &result.hits[&root.join("a.ts")];
106	/// assert_eq!((lines[0].line_number, lines[0].text.as_str()), (1, "const Alpha = 1;"));
107	/// assert_eq!(result.files_total, 1);
108	/// # Ok::<(), Box<dyn std::error::Error>>(())
109	/// ```
110	pub fn search_files(root: &Utf8Path, patterns: &[&str], opts: &TextSearchOptions) -> Result<TextSearchResult> {
111	    let matcher = compile(patterns)?;
112	    let root_error = |source| MonoklError::Walk { path: root.to_owned(), source };
113	    let metadata = std::fs::metadata(root).map_err(|e| root_error(ignore::Error::Io(e)))?;
114	    if !metadata.is_dir() {
115	        return Err(root_error(ignore::Error::Io(io::Error::from(io::ErrorKind::NotADirectory))));
116	    }
117	    // Listed here as well as by the walk, so a root that cannot be listed fails even when there is nothing to search.
118	    std::fs::read_dir(root).map_err(|e| root_error(ignore::Error::Io(e)))?;
119	    let mut result = TextSearchResult::default();
120	    let Some(matcher) = matcher else {
121	        return Ok(result);
122	    };
123	    // Passthru hands every line to the sink, so a CRLF line the matcher rejected because it saw the `\r` can still be
124	    // checked against its text without the terminator. BOM sniffing is off so a UTF-16 file's NUL bytes mark it binary
125	    // and a UTF-8 BOM stays in the first line's text instead of being decoded away.
126	    let mut searcher_builder = SearcherBuilder::new();
127	    searcher_builder.binary_detection(BinaryDetection::quit(b'\x00')).bom_sniffing(false).passthru(true);
128	    // The `ignore` crate's own parent support reads every ancestor up to `/`, so the walk covers the root and the
129	    // repository's parent files are applied by `ParentIgnores`. Global and `.git/info/exclude` rules stay off so the
130	    // same checkout gives the same result on every machine.
131	    let parents = if opts.respect_ignore_files { ParentIgnores::load(root, &mut result) } else { None };
132	    let mut builder = WalkBuilder::new(root);
133	    builder
134	        .standard_filters(opts.respect_ignore_files)
135	        .parents(false)
136	        .git_global(false)
137	        .git_exclude(false)
138	        .require_git(false)
139	        .sort_by_file_name(std::cmp::Ord::cmp);
140	    if let Some(parents) = parents {
141	        let root = root.to_owned();
142	        builder.filter_entry(move |entry| {
143	            let Some(path) = Utf8Path::from_path(entry.path()) else { return true };
144	            let Ok(relative) = path.strip_prefix(&root) else { return true };
145	            !parents.excludes(relative, entry.file_type().is_some_and(|file_type| file_type.is_dir()))
146	        });
147	    }
148	    let walk = builder.build();
149	    let mut paths = Vec::new();
150	    for entry in walk {
151	        let entry = match entry {
152	            Ok(entry) => entry,
153	            Err(err) if err.depth() == Some(0) => return Err(root_error(err)),
154	            Err(err) => {
155	                record_walk_error(&err, &mut result);
156	                continue;
157	            }
158	        };
159	        if let Some(err) = entry.error() {
160	            record_walk_error(err, &mut result);
161	        }
162	        if !entry.file_type().is_some_and(|file_type| file_type.is_file()) {
163	            continue;
164	        }
165	        let Ok(path) = Utf8PathBuf::from_path_buf(entry.into_path()) else {
166	            result.non_utf8_paths += 1;
167	            continue;
168	        };
169	        if !opts.allow_tests && is_test_path(path.strip_prefix(root).unwrap_or(&path)) {
170	            continue;
171	        }
172	        paths.push(path);
173	    }
174	    // Files are searched on separate threads and folded in walk order, so the result and the ceiling never depend on
175	    // which thread finished first.
176	    let outcomes: Vec<(Utf8PathBuf, FileOutcome)> = paths
177	        .into_par_iter()
178	        .map_init(
179	            || searcher_builder.build(),
180	            |searcher, path| {
181	                let outcome = search_file(searcher, &matcher, &path);
182	                (path, outcome)
183	            },
184	        )
185	        .collect();
186	    for (path, outcome) in outcomes {
187	        match outcome {
188	            FileOutcome::Binary => {}
189	            FileOutcome::Unreadable => result.unreadable.push(path),
190	            FileOutcome::Lines(hits) => {
191	                if hits.is_empty() {
192	                    continue;
193	                }
194	                result.files_total += 1;
195	                if result.hits.len() < opts.max_files {
196	                    result.hits.insert(path, hits);
197	                } else {
198	                    result.ceiling_hit = true;
199	                }
200	            }
201	        }
202	    }
203	    Ok(result)
204	}
205	
206	/// The `.ignore` and `.gitignore` rules of the directories from a git repository's root down to the search root's
207	/// parent, applied as the `ignore` crate applies parent files: a rule nearer the entry wins, `.ignore` wins over
208	/// `.gitignore` in one directory, and rules inside the search root win over all of them.
209	struct ParentIgnores {
210	    /// The canonical search root, which the matchers' paths are built from.
211	    base: Utf8PathBuf,
212	    /// Nearest directory first.
213	    parents: Vec<DirRules>,
214	    /// Rules of the directories inside the root, read when first needed.
215	    inside: Mutex<FxHashMap<Utf8PathBuf, Arc<DirRules>>>,
216	}
217	
218	/// One directory's `.ignore` and `.gitignore` files.
219	struct DirRules {
220	    ignore: Gitignore,
221	    gitignore: Gitignore,
222	}
223	
224	impl DirRules {
225	    /// Reads the directory's rules, with the errors from files that could not be read or parsed.
226	    fn read(dir: &Utf8Path) -> (Self, Vec<ignore::Error>) {
227	        let (ignore, ignore_err) = Gitignore::new(dir.join(".ignore"));
228	        let (gitignore, gitignore_err) = Gitignore::new(dir.join(".gitignore"));
229	        (Self { ignore, gitignore }, ignore_err.into_iter().chain(gitignore_err).collect())
230	    }
231	
232	    /// Whether either file has a rule, ignoring or whitelisting, that matches. `Some(true)` is an ignore.
233	    fn verdict(&self, path: &Utf8Path, is_dir: bool) -> Option<bool> {
234	        let matched =
235	            self.ignore.matched(path, is_dir).map(|_| ()).or(self.gitignore.matched(path, is_dir).map(|_| ()));
236	        match matched {
237	            ignore::Match::None => None,
238	            ignore::Match::Ignore(()) => Some(true),
239	            ignore::Match::Whitelist(()) => Some(false),
240	        }
241	    }
242	}
243	
244	impl ParentIgnores {
245	    /// Reads the parent rules for `root`, or `None` when `root` has no `.git` ancestor, is itself the repository
246	    /// root, or no parent directory has a rule. Read errors go in `result` like walk errors do.
247	    fn load(root: &Utf8Path, result: &mut TextSearchResult) -> Option<Self> {
248	        let base = root.canonicalize_utf8().ok()?;
249	        let repo_root = base.ancestors().find(|dir| dir.join(".git").symlink_metadata().is_ok())?;
250	        let mut parents = Vec::new();
251	        for dir in base.ancestors().skip(1).take_while(|dir| dir.starts_with(repo_root)) {
252	            let (rules, errors) = DirRules::read(dir);
253	            for err in &errors {
254	                record_walk_error(err, result);
255	            }
256	            parents.push(rules);
257	        }
258	        parents.iter().any(|rules| !rules.ignore.is_empty() || !rules.gitignore.is_empty()).then(|| Self {
259	            base,
260	            parents,
261	            inside: Mutex::new(FxHashMap::default()),
262	        })
263	    }
264	
265	    /// Whether a parent rule excludes the entry at `relative` below the root, and no rule inside the root matches it.
266	    fn excludes(&self, relative: &Utf8Path, is_dir: bool) -> bool {
267	        if relative.as_str().is_empty() {
268	            return false;
269	        }
270	        let path = self.base.join(relative);
271	        let decided_inside = path
272	            .ancestors()
273	            .skip(1)
274	            .take_while(|dir| dir.starts_with(&self.base))
275	            .any(|dir| self.inside_rules(dir).verdict(&path, is_dir).is_some());
276	        if decided_inside {
277	            return false;
278	        }
279	        self.parents.iter().find_map(|rules| rules.verdict(&path, is_dir)).unwrap_or(false)
280	    }
281	
282	    fn inside_rules(&self, dir: &Utf8Path) -> Arc<DirRules> {
283	        let mut cache = self.inside.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
284	        // Read errors are dropped: the walk reads the same files and reports them.
285	        Arc::clone(cache.entry(dir.to_owned()).or_insert_with(|| Arc::new(DirRules::read(dir).0)))
286	    }
287	}
288	
289	/// Compiles each pattern alone, then all together, so an invalid one always fails the search. `None` when there are no
290	/// patterns.
291	fn compile(patterns: &[&str]) -> Result<Option<RegexMatcher>> {
292	    let mut builder = RegexMatcherBuilder::new();
293	    builder.case_insensitive(true);
294	    // `build_many` joins the patterns with `|` before parsing, so halves such as `(a` and `b)` would compile together.
295	    for pattern in patterns {
296	        builder.build(pattern)?;
297	    }
298	    if patterns.is_empty() {
299	        return Ok(None);
300	    }
301	    Ok(Some(builder.build_many(patterns)?))
302	}
303	
304	/// Lists the path a walk error names in `unreadable`, or counts it when it names none that is UTF-8.
305	fn record_walk_error(err: &ignore::Error, result: &mut TextSearchResult) {
306	    match err {
307	        ignore::Error::Partial(errs) => {
308	            for err in errs {
309	                record_walk_error(err, result);
310	            }
311	        }
312	        ignore::Error::WithPath { path, .. } | ignore::Error::Loop { child: path, .. } => {
313	            match Utf8Path::from_path(path) {
314	                Some(path) if result.unreadable.iter().any(|listed| listed == path) => {}
315	                Some(path) => result.unreadable.push(path.to_owned()),
316	                None => result.walk_errors_without_path += 1,
317	            }
318	        }
319	        ignore::Error::WithDepth { err, .. } | ignore::Error::WithLineNumber { err, .. } => {
320	            record_walk_error(err, result);
321	        }
322	        ignore::Error::Io(_)
323	        | ignore::Error::Glob { .. }
324	        | ignore::Error::UnrecognizedFileType(_)
325	        | ignore::Error::InvalidDefinition => result.walk_errors_without_path += 1,
326	    }
327	}
328	
329	/// How searching one file ended.
330	enum FileOutcome {
331	    Binary,
332	    Unreadable,
333	    /// The file's matching lines, possibly none.
334	    Lines(Vec<LineHit>),
335	}
336	
337	fn search_file(searcher: &mut Searcher, matcher: &RegexMatcher, path: &Utf8Path) -> FileOutcome {
338	    let mut sink = LineCollector::new(matcher);
339	    match searcher.search_path(matcher, path.as_std_path(), &mut sink) {
340	        Err(_) => FileOutcome::Unreadable,
341	        Ok(()) if sink.binary => FileOutcome::Binary,
342	        Ok(()) => FileOutcome::Lines(sink.hits),
343	    }
344	}
345	
346	/// Collects matching lines, and stops at the first sign of binary data so the caller can discard the whole file,
347	/// including lines matched before the NUL byte was reached. A matching line that is not UTF-8 is kept with its invalid
348	/// bytes replaced by U+FFFD, and does not stop the search, so a NUL later in the file still marks it binary.
349	///
350	/// The searcher strips only the `\n` before matching, so a line ending in `\r\n` is matched again here against its
351	/// text without the terminator: a pattern always sees exactly the text a hit reports.
352	struct LineCollector<'m> {
353	    matcher: &'m RegexMatcher,
354	    /// Matches one CRLF line's text, which holds no `\n`, so it searches it as a single line.
355	    line_searcher: Searcher,
356	    /// Reused to hold the text [`Self::line_searcher`] searches.
357	    line_buf: Vec<u8>,
358	    hits: Vec<LineHit>,
359	    binary: bool,
360	}
361	
362	impl<'m> LineCollector<'m> {
363	    fn new(matcher: &'m RegexMatcher) -> Self {
364	        Self {
365	            matcher,
366	            line_searcher: SearcherBuilder::new().bom_sniffing(false).build(),
367	            line_buf: Vec::new(),
368	            hits: Vec::new(),
369	            binary: false,
370	        }
371	    }
372	
373	    /// Records `line` as a hit when it matches. `searcher_matched` is the searcher's verdict, which is final unless the
374	    /// line ends in `\r\n`.
375	    fn line(&mut self, line_number: Option<u64>, line: &[u8], searcher_matched: bool) -> io::Result<()> {
376	        let text = without_line_terminator(line);
377	        let matched = if line.ends_with(b"\r\n") { self.text_matches(text)? } else { searcher_matched };
378	        if !matched {
379	            return Ok(());
380	        }
381	        let line_number = line_number
382	            .and_then(|line_number| usize::try_from(line_number).ok())
383	            .ok_or_else(|| io::Error::other("matched line has no usable line number"))?;
384	        self.hits.push(LineHit { line_number, text: String::from_utf8_lossy(text).into_owned() });
385	        Ok(())
386	    }
387	
388	    fn text_matches(&mut self, text: &[u8]) -> io::Result<bool> {
389	        // An empty slice has no lines to match, so the text is searched as one `\n`-terminated line, which the
390	        // searcher strips again before matching.
391	        self.line_buf.clear();
392	        self.line_buf.extend_from_slice(text);
393	        self.line_buf.push(b'\n');
394	        let mut found = AnyMatch(false);
395	        self.line_searcher.search_slice(self.matcher, &self.line_buf, &mut found)?;
396	        Ok(found.0)
397	    }
398	}
399	
400	impl Sink for LineCollector<'_> {
401	    type Error = io::Error;
402	
403	    fn matched(&mut self, _searcher: &Searcher, mat: &SinkMatch<'_>) -> io::Result<bool> {
404	        self.line(mat.line_number(), mat.bytes(), true)?;
405	        Ok(true)
406	    }
407	
408	    fn context(&mut self, _searcher: &Searcher, context: &SinkContext<'_>) -> io::Result<bool> {
409	        self.line(context.line_number(), context.bytes(), false)?;
410	        Ok(true)
411	    }
412	
413	    fn binary_data(&mut self, _searcher: &Searcher, _binary_byte_offset: u64) -> io::Result<bool> {
414	        self.binary = true;
415	        Ok(false)
416	    }
417	}
418	
419	/// Records whether a search found any match, stopping at the first.
420	struct AnyMatch(bool);

