        TextSearchResult {
            hits: hits(&root, &[("b.ts", vec![hit(1, "alpha")]), ("zz.ts", vec![hit(1, "alpha")])]),
            files_total: 2,
            unreadable: vec![root.join("a.ts"), root.join("z")],
            ..TextSearchResult::default()
        }
    );
}

