32	    let peak = ALLOCATOR.peak_usage();
33	
34	    assert_eq!(result.files_total, FILES as u64);
35	    assert!(result.ceiling_hit);
36	    assert_eq!(result.hits.keys().map(|path| path.file_name()).collect::<Vec<_>>(), [Some("f0000.ts")]);
37	    assert!(peak < all_hits / 3, "peak {peak} bytes is not well below all hits at {all_hits} bytes");
38	    Ok(())
39	}
